insert into public.questions (id, position, set_name, sentence, words) values ('W1', 1, 'Warm-up', 'The singer, along with her band, was rehearsing.', array['The','singer,','along','with','her','band,','was','rehearsing.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('W1', array[1]::int[], array[6, 7]::int[], '"Along with her band" is an interrupter, not part of the subject, so the subject is "singer." The helping verb "was" and the main verb "rehearsing" together form the predicate.', 'band');
insert into public.questions (id, position, set_name, sentence, words) values ('W2', 2, 'Warm-up', 'Neither the coach nor the players were told about the change.', array['Neither','the','coach','nor','the','players','were','told','about','the','change.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('W2', array[2, 5]::int[], array[6, 7]::int[], 'Neither...nor joins two subjects, so both "coach" and "players" count. "Were told" is the verb phrase; "about the change" is a prepositional phrase.', 'change');
insert into public.questions (id, position, set_name, sentence, words) values ('W3', 3, 'Warm-up', 'Rarely do we see such talent.', array['Rarely','do','we','see','such','talent.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('W3', array[2]::int[], array[1, 3]::int[], 'Put it in normal order: "We do rarely see such talent." The subject is "we," and the predicate is the split verb "do ... see."', 'talent');
insert into public.questions (id, position, set_name, sentence, words) values ('W4', 4, 'Warm-up', 'Only after the storm did the power return.', array['Only','after','the','storm','did','the','power','return.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('W4', array[6]::int[], array[4, 7]::int[], 'Normal order: "The power did return only after the storm." "Storm" is inside a prepositional phrase, so it can''t be the subject.', 'storm');
insert into public.questions (id, position, set_name, sentence, words) values ('W5', 5, 'Warm-up', 'Off the coast of Maine lie hundreds of small islands.', array['Off','the','coast','of','Maine','lie','hundreds','of','small','islands.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('W5', array[6]::int[], array[5]::int[], 'Normal order: "Hundreds of small islands lie off the coast of Maine." "Islands" sits inside "of small islands," so the subject is "hundreds."', 'coast, Maine, islands');
insert into public.questions (id, position, set_name, sentence, words) values ('C1', 6, 'Challenge', 'The collection of rare manuscripts, letters, and maps that the historians spent years cataloging is now housed in the university library.', array['The','collection','of','rare','manuscripts,','letters,','and','maps','that','the','historians','spent','years','cataloging','is','now','housed','in','the','university','library.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C1', array[1]::int[], array[14, 16]::int[], 'Ask what "is housed": the collection. "Manuscripts, letters, and maps" sit inside an "of" phrase, and "spent" belongs to the clause "that the historians spent...". "Now" is an adverb.', 'manuscripts, maps, historians, spent, cataloging');
insert into public.questions (id, position, set_name, sentence, words) values ('C2', 7, 'Challenge', 'Exhausted from hours of rehearsing the difficult passages that the conductor had added, the violinists in the second row finally lowered their instruments.', array['Exhausted','from','hours','of','rehearsing','the','difficult','passages','that','the','conductor','had','added,','the','violinists','in','the','second','row','finally','lowered','their','instruments.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C2', array[14]::int[], array[20]::int[], 'The opening phrase ("Exhausted...") describes the violinists and has no verb of its own. "Had added" belongs to the "that" clause, and "row" is inside "in the second row."', 'Exhausted, rehearsing, conductor, had added, row');
insert into public.questions (id, position, set_name, sentence, words) values ('C3', 8, 'Medium', 'The keys to the storage room are hanging by the door.', array['The','keys','to','the','storage','room','are','hanging','by','the','door.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C3', array[1]::int[], array[6, 7]::int[], '"Room" is inside the phrase "to the storage room," so it can''t be the subject. The plural "keys" takes "are hanging."', 'room, door');
insert into public.questions (id, position, set_name, sentence, words) values ('C4', 9, 'Challenge', 'Along the old railroad tracks, which had been abandoned decades earlier by a company that went bankrupt, run a narrow footpath and a row of crumbling stone walls.', array['Along','the','old','railroad','tracks,','which','had','been','abandoned','decades','earlier','by','a','company','that','went','bankrupt,','run','a','narrow','footpath','and','a','row','of','crumbling','stone','walls.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C4', array[20, 23]::int[], array[17]::int[], 'Normal order: "A footpath and a row ... run along the tracks." "Had been abandoned" and "went" belong to side clauses, and "walls" is inside "of crumbling stone walls."', 'tracks, had been abandoned, company, went, walls');
insert into public.questions (id, position, set_name, sentence, words) values ('C5', 10, 'Challenge', 'Each of the paintings displayed in the gallery''s newest wing, including several portraits attributed to Rembrandt''s students, was carefully restored.', array['Each','of','the','paintings','displayed','in','the','gallery''s','newest','wing,','including','several','portraits','attributed','to','Rembrandt''s','students,','was','carefully','restored.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C5', array[0]::int[], array[17, 19]::int[], '"Each" is the subject, which is why the verb is singular "was." "Paintings" is inside "of the paintings," and "displayed" and "attributed" are participles.', 'paintings, displayed, portraits, attributed');
insert into public.questions (id, position, set_name, sentence, words) values ('C6', 11, 'Medium', 'My aunt, a nurse in Chicago, works the night shift.', array['My','aunt,','a','nurse','in','Chicago,','works','the','night','shift.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C6', array[1]::int[], array[6]::int[], '"A nurse in Chicago" is an appositive that renames "aunt." Ask who works: my aunt.', 'nurse, Chicago, shift');
insert into public.questions (id, position, set_name, sentence, words) values ('C7', 12, 'Medium', 'Each of the runners wore a bright orange vest.', array['Each','of','the','runners','wore','a','bright','orange','vest.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C7', array[0]::int[], array[4]::int[], '"Runners" is inside "of the runners." The subject is "Each."', 'runners, vest');
insert into public.questions (id, position, set_name, sentence, words) values ('C8', 13, 'Medium', 'After the long meeting, the manager sent everyone home early.', array['After','the','long','meeting,','the','manager','sent','everyone','home','early.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C8', array[5]::int[], array[6]::int[], '"After the long meeting" is an opening prepositional phrase. "Everyone" receives the action; the manager does the sending.', 'meeting, everyone');
insert into public.questions (id, position, set_name, sentence, words) values ('C9', 14, 'Challenge', 'The scientist whose research on coral reefs earned her international recognition, along with two graduate students from her lab, is traveling to Australia next month.', array['The','scientist','whose','research','on','coral','reefs','earned','her','international','recognition,','along','with','two','graduate','students','from','her','lab,','is','traveling','to','Australia','next','month.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C9', array[1]::int[], array[19, 20]::int[], 'The "whose" clause has its own verb ("earned"), and "along with two graduate students" is an interrupter. The singular "is traveling" agrees with "scientist."', 'research, earned, students');
insert into public.questions (id, position, set_name, sentence, words) values ('C10', 15, 'Medium', 'The students in the back row have finished the test.', array['The','students','in','the','back','row','have','finished','the','test.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C10', array[1]::int[], array[6, 7]::int[], '"Row" is inside "in the back row." Include the helping verb: "have finished."', 'row, test');
insert into public.questions (id, position, set_name, sentence, words) values ('C11', 16, 'Challenge', 'The number of students who say that they feel overwhelmed by homework has risen sharply.', array['The','number','of','students','who','say','that','they','feel','overwhelmed','by','homework','has','risen','sharply.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C11', array[1]::int[], array[12, 13]::int[], '"The number" is singular, so it takes "has risen." "Students," "say," and "feel" belong to the phrase and clauses that describe it.', 'students, say, feel, overwhelmed');
insert into public.questions (id, position, set_name, sentence, words) values ('C12', 17, 'Medium', 'There were several mistakes in the final report.', array['There','were','several','mistakes','in','the','final','report.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C12', array[3]::int[], array[1]::int[], '"There" is never the subject. Normal order: "Several mistakes were in the final report."', 'There, report');
insert into public.questions (id, position, set_name, sentence, words) values ('C13', 18, 'Challenge', 'Neither the lead actor nor the understudies, all of whom had memorized the revised script, were ready for the director''s sudden changes.', array['Neither','the','lead','actor','nor','the','understudies,','all','of','whom','had','memorized','the','revised','script,','were','ready','for','the','director''s','sudden','changes.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C13', array[3, 6]::int[], array[15]::int[], 'Neither...nor joins two subjects. "Had memorized" belongs to the "all of whom" clause, and "were" is a linking verb ("ready" describes the subjects).', 'all, had memorized');
insert into public.questions (id, position, set_name, sentence, words) values ('C14', 19, 'Challenge', 'The painting hanging above the fireplace in the study where my grandfather wrote his novels belonged to his mother.', array['The','painting','hanging','above','the','fireplace','in','the','study','where','my','grandfather','wrote','his','novels','belonged','to','his','mother.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C14', array[1]::int[], array[15]::int[], '"Hanging" is a participle describing the painting. "Wrote" belongs to the "where" clause.', 'hanging, study, grandfather, wrote');
insert into public.questions (id, position, set_name, sentence, words) values ('C15', 20, 'Challenge', 'Only by carefully reviewing the data collected from hundreds of patients over a decade could the researchers confirm their hypothesis.', array['Only','by','carefully','reviewing','the','data','collected','from','hundreds','of','patients','over','a','decade','could','the','researchers','confirm','their','hypothesis.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C15', array[16]::int[], array[14, 17]::int[], 'Normal order: "The researchers could confirm their hypothesis only by reviewing..." "Reviewing" is a gerund and "collected" is a participle.', 'reviewing, data, collected, patients');
insert into public.questions (id, position, set_name, sentence, words) values ('C16', 21, 'Challenge', 'The list of items that the hikers forgot to pack, which included a map, a compass, and extra water, was alarmingly long.', array['The','list','of','items','that','the','hikers','forgot','to','pack,','which','included','a','map,','a','compass,','and','extra','water,','was','alarmingly','long.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C16', array[1]::int[], array[19]::int[], '"Items" is inside "of items." "Forgot" and "included" belong to side clauses, and "to pack" is an infinitive.', 'items, hikers, forgot, to pack, included');
insert into public.questions (id, position, set_name, sentence, words) values ('C17', 22, 'Medium', 'The dog that lives next door barks at every passing car.', array['The','dog','that','lives','next','door','barks','at','every','passing','car.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C17', array[1]::int[], array[6]::int[], '"Lives" belongs to the "that" clause describing the dog. The main verb is "barks."', 'lives, door, passing, car');
insert into public.questions (id, position, set_name, sentence, words) values ('C18', 23, 'Challenge', 'The effects of the new policy, which critics claimed would harm small businesses, have been surprisingly modest.', array['The','effects','of','the','new','policy,','which','critics','claimed','would','harm','small','businesses,','have','been','surprisingly','modest.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C18', array[1]::int[], array[13, 14]::int[], 'Plural "effects" takes "have been." "Claimed" and "would harm" belong to the "which" clause.', 'policy, critics, claimed, would harm');
insert into public.questions (id, position, set_name, sentence, words) values ('C19', 24, 'Medium', 'A box of old letters was found in the basement.', array['A','box','of','old','letters','was','found','in','the','basement.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C19', array[1]::int[], array[5, 6]::int[], '"Letters" is inside "of old letters." Singular "box" takes "was found."', 'letters, basement');
insert into public.questions (id, position, set_name, sentence, words) values ('C20', 25, 'Medium', 'During the storm, the lights in the gym flickered twice.', array['During','the','storm,','the','lights','in','the','gym','flickered','twice.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C20', array[4]::int[], array[8]::int[], '"Storm" and "gym" are inside prepositional phrases. The lights flickered.', 'storm, gym');
insert into public.questions (id, position, set_name, sentence, words) values ('C21', 26, 'Challenge', 'Among the documents discovered in the attic of the abandoned farmhouse was a letter signed by Abraham Lincoln.', array['Among','the','documents','discovered','in','the','attic','of','the','abandoned','farmhouse','was','a','letter','signed','by','Abraham','Lincoln.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C21', array[13]::int[], array[11]::int[], 'Normal order: "A letter was among the documents." "Discovered" and "signed" are participles.', 'documents, discovered, farmhouse, signed');
insert into public.questions (id, position, set_name, sentence, words) values ('C22', 27, 'Challenge', 'The teacher''s insistence that every student rewrite the essay, regardless of the grade earned on the first draft, frustrated the class.', array['The','teacher''s','insistence','that','every','student','rewrite','the','essay,','regardless','of','the','grade','earned','on','the','first','draft,','frustrated','the','class.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C22', array[2]::int[], array[18]::int[], '"Rewrite" belongs to the "that" clause after "insistence," and "earned" is a participle. Ask what frustrated the class: the insistence.', 'student, rewrite, grade, earned');
insert into public.questions (id, position, set_name, sentence, words) values ('C23', 28, 'Challenge', 'The flock of geese flying south for the winter, honking loudly as they passed over the lake, was visible from miles away.', array['The','flock','of','geese','flying','south','for','the','winter,','honking','loudly','as','they','passed','over','the','lake,','was','visible','from','miles','away.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C23', array[1]::int[], array[17]::int[], '"Flying" and "honking" are participles, and "passed" belongs to the "as" clause. Singular "flock" takes "was."', 'geese, flying, honking, passed');
insert into public.questions (id, position, set_name, sentence, words) values ('C24', 29, 'Challenge', 'To the surprise of everyone attending the ceremony, the award for outstanding service went to the janitor, who had worked at the school for forty years.', array['To','the','surprise','of','everyone','attending','the','ceremony,','the','award','for','outstanding','service','went','to','the','janitor,','who','had','worked','at','the','school','for','forty','years.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C24', array[9]::int[], array[13]::int[], '"To the surprise of everyone" is an opening prepositional phrase, and "attending" is a participle. "Had worked" belongs to the "who" clause about the janitor.', 'surprise, attending, service, janitor, had worked');
insert into public.questions (id, position, set_name, sentence, words) values ('C25', 30, 'Medium', 'The new library, which opened in March, has a rooftop garden.', array['The','new','library,','which','opened','in','March,','has','a','rooftop','garden.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C25', array[2]::int[], array[7]::int[], '"Opened" belongs to the "which" clause. The main verb is "has."', 'opened, March, garden');
insert into public.questions (id, position, set_name, sentence, words) values ('C26', 31, 'Challenge', 'Seldom have the members of the city council, a group known for its bitter disagreements, voted unanimously.', array['Seldom','have','the','members','of','the','city','council,','a','group','known','for','its','bitter','disagreements,','voted','unanimously.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C26', array[3]::int[], array[1, 15]::int[], 'Normal order: "The members have seldom voted unanimously." "A group known for..." is an appositive describing the council.', 'council, group, known');
insert into public.questions (id, position, set_name, sentence, words) values ('C27', 32, 'Challenge', 'The recipe, handed down through five generations of my mother''s family and scribbled on a yellowed index card, requires three kinds of chocolate.', array['The','recipe,','handed','down','through','five','generations','of','my','mother''s','family','and','scribbled','on','a','yellowed','index','card,','requires','three','kinds','of','chocolate.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C27', array[1]::int[], array[18]::int[], '"Handed" and "scribbled" are participles set off by commas, not verbs. The recipe requires chocolate.', 'handed, scribbled, generations, card');
insert into public.questions (id, position, set_name, sentence, words) values ('C28', 33, 'Medium', 'Neither my brother nor my sister likes spicy food.', array['Neither','my','brother','nor','my','sister','likes','spicy','food.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C28', array[2, 5]::int[], array[6]::int[], 'Neither...nor joins two subjects, so both count. The verb agrees with the nearer subject, "sister."', 'food');
insert into public.questions (id, position, set_name, sentence, words) values ('C29', 34, 'Challenge', 'A series of mistakes made by the engineers responsible for designing the bridge''s supports was blamed for the collapse.', array['A','series','of','mistakes','made','by','the','engineers','responsible','for','designing','the','bridge''s','supports','was','blamed','for','the','collapse.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C29', array[1]::int[], array[14, 15]::int[], '"Series" is singular, so it takes "was blamed." "Mistakes" and "engineers" sit inside phrases, and "made" and "designing" are verbals.', 'mistakes, made, engineers, designing');
insert into public.questions (id, position, set_name, sentence, words) values ('C30', 35, 'Challenge', 'The athlete who had trained for years to qualify for the Olympics, only to be injured weeks before the trials, now coaches young runners.', array['The','athlete','who','had','trained','for','years','to','qualify','for','the','Olympics,','only','to','be','injured','weeks','before','the','trials,','now','coaches','young','runners.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C30', array[1]::int[], array[21]::int[], '"Had trained" belongs to the "who" clause, and "to qualify" and "to be injured" are infinitives. "Now" is an adverb.', 'had trained, to qualify, to be injured');
insert into public.questions (id, position, set_name, sentence, words) values ('C31', 36, 'Challenge', 'In the corner of the museum''s dimly lit east gallery, protected by a glass case and guarded by two security officers, sits a diamond the size of a walnut.', array['In','the','corner','of','the','museum''s','dimly','lit','east','gallery,','protected','by','a','glass','case','and','guarded','by','two','security','officers,','sits','a','diamond','the','size','of','a','walnut.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C31', array[23]::int[], array[21]::int[], 'Normal order: "A diamond sits in the corner of the gallery." "Protected" and "guarded" are participles describing the diamond.', 'corner, gallery, protected, guarded, officers');
insert into public.questions (id, position, set_name, sentence, words) values ('C32', 37, 'Medium', 'The coach and her assistant will review the game film tomorrow.', array['The','coach','and','her','assistant','will','review','the','game','film','tomorrow.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C32', array[1, 4]::int[], array[5, 6]::int[], '"And" joins two subjects. Include the helping verb: "will review."', 'game, film');
insert into public.questions (id, position, set_name, sentence, words) values ('C33', 38, 'Challenge', 'Keeping a journal, a habit that many successful writers credit with sharpening their observational skills, takes only a few minutes a day.', array['Keeping','a','journal,','a','habit','that','many','successful','writers','credit','with','sharpening','their','observational','skills,','takes','only','a','few','minutes','a','day.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C33', array[0]::int[], array[15]::int[], '"Keeping a journal" is a gerund phrase acting as the subject. "A habit that..." renames it, and "credit" belongs to that clause.', 'journal, habit, writers, credit, sharpening');
insert into public.questions (id, position, set_name, sentence, words) values ('C34', 39, 'Medium', 'Walking to school every day keeps Maya healthy.', array['Walking','to','school','every','day','keeps','Maya','healthy.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C34', array[0]::int[], array[5]::int[], '"Walking to school" is a gerund phrase acting as the subject. "Maya" is the object of "keeps."', 'school, Maya');
insert into public.questions (id, position, set_name, sentence, words) values ('C35', 40, 'Challenge', 'The reasons the company gave for canceling the product, most of which were vague, did not satisfy shareholders.', array['The','reasons','the','company','gave','for','canceling','the','product,','most','of','which','were','vague,','did','not','satisfy','shareholders.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C35', array[1]::int[], array[14, 16]::int[], '"The company gave" is a side clause describing the reasons, and "were" belongs to "most of which were vague." "Not" is an adverb.', 'company, gave, canceling, most, were');
insert into public.questions (id, position, set_name, sentence, words) values ('C36', 41, 'Medium', 'The price of the concert tickets has doubled since last year.', array['The','price','of','the','concert','tickets','has','doubled','since','last','year.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C36', array[1]::int[], array[6, 7]::int[], '"Tickets" is inside "of the concert tickets." Singular "price" takes "has doubled."', 'tickets, year');
insert into public.questions (id, position, set_name, sentence, words) values ('C37', 42, 'Medium', 'Did the bus driver see the stop sign?', array['Did','the','bus','driver','see','the','stop','sign?']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C37', array[3]::int[], array[0, 4]::int[], 'Statement form: "The bus driver did see the stop sign." "Bus" describes the driver, and the verb is split: "Did ... see."', 'bus, sign');
insert into public.questions (id, position, set_name, sentence, words) values ('C38', 43, 'Medium', 'In the middle of the lake sits a tiny island.', array['In','the','middle','of','the','lake','sits','a','tiny','island.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C38', array[9]::int[], array[6]::int[], 'Normal order: "A tiny island sits in the middle of the lake." "Middle" and "lake" are inside prepositional phrases.', 'middle, lake');
insert into public.questions (id, position, set_name, sentence, words) values ('C39', 44, 'Challenge', 'The old man sitting on the bench feeding pigeons, whom the neighborhood children call "the Professor," was once a famous mathematician.', array['The','old','man','sitting','on','the','bench','feeding','pigeons,','whom','the','neighborhood','children','call','"the','Professor,"','was','once','a','famous','mathematician.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C39', array[2]::int[], array[16]::int[], '"Sitting" and "feeding" are participles, and "call" belongs to the "whom" clause. "Once" is an adverb.', 'sitting, feeding, pigeons, children, call');
insert into public.questions (id, position, set_name, sentence, words) values ('C40', 45, 'Medium', 'The painting on the wall was created by a local artist.', array['The','painting','on','the','wall','was','created','by','a','local','artist.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C40', array[1]::int[], array[5, 6]::int[], '"Wall" is inside "on the wall," and "artist" is inside "by a local artist." The painting was created.', 'wall, artist');
insert into public.questions (id, position, set_name, sentence, words) values ('C41', 46, 'Challenge', 'The diversity of plant species found in the rainforest canopy, much of which remains unexplored, rivals that of entire continents.', array['The','diversity','of','plant','species','found','in','the','rainforest','canopy,','much','of','which','remains','unexplored,','rivals','that','of','entire','continents.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C41', array[1]::int[], array[15]::int[], '"Species" is inside "of plant species," "found" is a participle, and "remains" belongs to the "much of which" clause.', 'species, found, canopy, much, remains');
insert into public.questions (id, position, set_name, sentence, words) values ('C42', 47, 'Challenge', 'Before them, stretching to the horizon under a sky streaked with pink and orange, lay the vast desert they would have to cross.', array['Before','them,','stretching','to','the','horizon','under','a','sky','streaked','with','pink','and','orange,','lay','the','vast','desert','they','would','have','to','cross.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C42', array[17]::int[], array[14]::int[], 'Normal order: "The vast desert lay before them." "Stretching" and "streaked" are participles, and "would have" belongs to the clause "they would have to cross."', 'them, stretching, sky, streaked, would have');
insert into public.questions (id, position, set_name, sentence, words) values ('C43', 48, 'Challenge', 'The committee''s report, praised by some for its thoroughness and criticized by others for its length, has not yet been released to the public.', array['The','committee''s','report,','praised','by','some','for','its','thoroughness','and','criticized','by','others','for','its','length,','has','not','yet','been','released','to','the','public.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C43', array[2]::int[], array[16, 19, 20]::int[], '"Praised" and "criticized" are participles set off by commas. "Not" and "yet" are adverbs inside the verb phrase.', 'praised, criticized');
insert into public.questions (id, position, set_name, sentence, words) values ('C44', 49, 'Challenge', 'Learning to play an instrument as an adult, despite the frustrations that inevitably accompany early practice, can be deeply rewarding.', array['Learning','to','play','an','instrument','as','an','adult,','despite','the','frustrations','that','inevitably','accompany','early','practice,','can','be','deeply','rewarding.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C44', array[0]::int[], array[16, 17]::int[], '"Learning to play an instrument" is a gerund phrase acting as the subject. "Rewarding" is an adjective after the linking verb "can be."', 'to play, instrument, frustrations, accompany, rewarding');
insert into public.questions (id, position, set_name, sentence, words) values ('C45', 50, 'Medium', 'One of the windows in the kitchen needs a new latch.', array['One','of','the','windows','in','the','kitchen','needs','a','new','latch.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C45', array[0]::int[], array[7]::int[], '"Windows" and "kitchen" are inside prepositional phrases. Singular "One" takes "needs."', 'windows, kitchen');
insert into public.questions (id, position, set_name, sentence, words) values ('C46', 51, 'Challenge', 'Either the students in the advanced section or their teacher is responsible for organizing the trip.', array['Either','the','students','in','the','advanced','section','or','their','teacher','is','responsible','for','organizing','the','trip.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C46', array[2, 9]::int[], array[10]::int[], 'Either...or joins two subjects; the verb agrees with the nearer one, "teacher," so it''s "is." "Organizing" is a gerund.', 'section, organizing');
insert into public.questions (id, position, set_name, sentence, words) values ('C47', 52, 'Medium', 'The cookies that Grandma baked disappeared within an hour.', array['The','cookies','that','Grandma','baked','disappeared','within','an','hour.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C47', array[1]::int[], array[5]::int[], '"Baked" belongs to the "that" clause, with "Grandma" as its subject. The cookies disappeared.', 'Grandma, baked');
insert into public.questions (id, position, set_name, sentence, words) values ('C48', 53, 'Medium', 'Hoping for a good grade, Marcus studied late into the night.', array['Hoping','for','a','good','grade,','Marcus','studied','late','into','the','night.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C48', array[5]::int[], array[6]::int[], '"Hoping for a good grade" is a participial phrase describing Marcus. The main verb is "studied."', 'Hoping, grade, night');
insert into public.questions (id, position, set_name, sentence, words) values ('C49', 54, 'Challenge', 'The students who the teacher believed had cheated on the exam were later cleared of any wrongdoing.', array['The','students','who','the','teacher','believed','had','cheated','on','the','exam','were','later','cleared','of','any','wrongdoing.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C49', array[1]::int[], array[11, 13]::int[], '"Believed" and "had cheated" belong to the "who the teacher believed" clause. "Later" is an adverb.', 'teacher, believed, had cheated');
insert into public.questions (id, position, set_name, sentence, words) values ('C50', 55, 'Challenge', 'Overlooking the harbor, where fishing boats painted in bright blues and reds bob gently in the morning tide, stands a lighthouse built in 1824.', array['Overlooking','the','harbor,','where','fishing','boats','painted','in','bright','blues','and','reds','bob','gently','in','the','morning','tide,','stands','a','lighthouse','built','in','1824.']::text[]) on conflict (id) do update set position=excluded.position, set_name=excluded.set_name, sentence=excluded.sentence, words=excluded.words;
insert into public.question_keys (question_id, subject_idx, predicate_idx, explanation, decoys) values ('C50', array[20]::int[], array[18]::int[], 'Normal order: "A lighthouse stands overlooking the harbor." "Bob" belongs to the "where" clause, and "painted" and "built" are participles.', 'Overlooking, harbor, boats, painted, bob, built');
